    score = 1
    for i in range(start, start + k):
        score *= cards[i]
    return abs(score)

def solution(cards, k):
    if len(cards) < k:
        return -1
    best_start = 0
    best = bundle_score(cards, 0, k)
    for s in range(1, len(cards) - k + 1):
        now = bundle_score(cards, s, k)
        if now > best:
            best = now
            best_start = s
    return best_start + 1

