    result = 1
    for ch in str(n):
        result *= int(ch)
        return result

def persistence(n):
    count = 0
    while n >= 10:
        n = digit_product(n)
        count += 1
    return count

def solution(lo, hi, k):
    total = 0
    smallest = -1
    for x in range(lo, hi + 1):
        if persistence(x) >= k:
            total += 1
            if smallest == -1:
                smallest = x
    return [total, smallest]

